CREATE TABLE IF NOT EXISTS followup_sequences(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,name TEXT NOT NULL,steps JSONB NOT NULL DEFAULT '[]'::jsonb,is_active BOOLEAN NOT NULL DEFAULT false,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());CREATE TABLE IF NOT EXISTS followup_enrollments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,sequence_id UUID NOT NULL REFERENCES followup_sequences(id) ON DELETE CASCADE,lead_id UUID REFERENCES leads(id) ON DELETE CASCADE,current_step INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'active',next_run_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());CREATE INDEX IF NOT EXISTS followup_due_idx ON followup_enrollments(tenant_id,status,next_run_at);